package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class CourseMyAssignmentsIntegrationTest {
 CourseStoreIntegrationTest f;CourseMyAssignmentsStore store;AssignmentStore assignments;SubmissionStore submissions;CourseStore.Course course;StudyStore.Study a,b;UUID actor;
 @BeforeEach void setup(){f=new CourseStoreIntegrationTest();f.setup();a=f.study();b=f.study();course=f.curriculum(f.create(f.f.key()).course(),a.studyId(),b.studyId());actor=f.f.ids.next();assignments=new AssignmentStore(f.f.source,f.parent.store,Clock.systemUTC());submissions=new SubmissionStore(f.f.source,assignments,Clock.systemUTC());store=new CourseMyAssignmentsStore(f.f.source,f.store);}
 UUID task(UUID study,String state){var id=assignments.create(f.group,f.space,study,f.f.owner,f.f.key(),"Task <script>","Shared instructions",f.f.trace).assignment().assignmentId();if(!state.equals("DRAFT"))assignments.state(f.group,f.space,study,id,f.f.owner,1,"OPEN",f.f.trace);if(state.equals("CLOSED")||state.equals("RETIRED"))assignments.state(f.group,f.space,study,id,f.f.owner,2,state,f.f.trace);return id;}
 SubmissionStore.Submission submit(UUID study,UUID task,UUID author){return submissions.submit(f.group,f.space,study,task,author,0,2,f.f.key(),"PRIVATE ANSWER",f.f.trace).submission();}
 CourseMyAssignmentsStore.Page list(String filter,UUID after,int limit){return store.list(f.group,f.space,course.courseId(),actor,after,limit,filter);}
 @Test void linkedStudiesOnlyWithActorOwnPresenceNeverPeerOrOwner(){
  UUID x=task(a.studyId(),"OPEN"),y=task(b.studyId(),"OPEN");var excluded=f.study();task(excluded.studyId(),"OPEN");var peer=submit(a.studyId(),x,f.f.ids.next());var owner=submit(a.studyId(),x,f.f.owner);var own=submit(b.studyId(),y,actor);assertEquals(2,list("ALL",null,20).items().size());assertEquals(x,list("OPEN_NOT_SUBMITTED",null,20).items().getFirst().assignmentId());assertNull(list("OPEN_NOT_SUBMITTED",null,20).items().getFirst().submissionId());assertEquals(own.submissionId(),list("SUBMITTED",null,20).items().getFirst().submissionId());assertEquals(owner.submissionId(),store.list(f.group,f.space,course.courseId(),f.f.owner,null,20,"SUBMITTED").items().getFirst().submissionId());var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(list("ALL",null,20).items().getFirst());assertEquals(11,json.size());for(String field:List.of("authorId","content","score","reason","total","canSubmit","description"))assertFalse(json.has(field));assertFalse(list("ALL",null,20).items().stream().anyMatch(v->v.submissionId()!=null&&v.submissionId().equals(peer.submissionId())));
 }
 @Test void emptyAndChangedCurriculumUseCurrentCanonicalBindings(){
  UUID x=task(a.studyId(),"OPEN"),y=task(b.studyId(),"OPEN");assertEquals(2,list("ALL",null,20).items().size());course=f.curriculum(course,b.studyId());assertEquals(List.of(y),list("ALL",null,20).items().stream().map(CourseMyAssignmentsStore.Row::assignmentId).toList());course=f.curriculum(course);assertTrue(list("ALL",null,20).items().isEmpty());course=f.curriculum(course,a.studyId());assertEquals(x,list("ALL",null,20).items().getFirst().assignmentId());
 }
 @Test void liveStudyAndAssignmentLabelsNeverRewritePinnedCourseOrSubmittedInstructions(){
  UUID x=task(a.studyId(),"OPEN");submit(a.studyId(),x,actor);f.parent.store.metadata(f.group,f.space,a.studyId(),f.f.owner,1,"Renamed current Study","New",f.f.trace);assignments.metadata(f.group,f.space,a.studyId(),x,f.f.owner,2,"Renamed current Task","New",f.f.trace);var v=list("ALL",null,20).items().getFirst();assertEquals("Renamed current Study",v.studyTitle());assertEquals("Renamed current Task",v.title());assertEquals(3,v.version());assertEquals(2L,v.submittedAssignmentVersion());assertEquals(a.title(),f.store.get(f.group,f.space,course.courseId()).studies().getFirst().title());assertEquals(1,f.store.get(f.group,f.space,course.courseId()).studies().getFirst().studyVersion());
 }
 @Test void courseAndStudyLifecycleFiltersRetainSharedReadsWithoutReopening(){
  task(a.studyId(),"OPEN");task(b.studyId(),"OPEN");task(b.studyId(),"DRAFT");task(b.studyId(),"CLOSED");task(b.studyId(),"RETIRED");course=f.state(course,"ACTIVE");course=f.state(course,"COMPLETED");assertEquals(2,list("OPEN",null,20).items().size());f.parent.store.state(f.group,f.space,a.studyId(),f.f.owner,1,"RETIRED",f.f.trace);assertEquals(1,list("OPEN_NOT_SUBMITTED",null,20).items().size());assertEquals(5,list("ALL",null,20).items().size());course=f.state(course,"RETIRED");assertTrue(list("OPEN",null,20).items().isEmpty());assertTrue(list("OPEN_NOT_SUBMITTED",null,20).items().isEmpty());assertEquals(5,list("ALL",null,20).items().size());assertTrue(list("ALL",null,20).items().stream().allMatch(v->v.courseState().equals("RETIRED")));
 }
 @Test void keysetAppliesPresenceAndParentPredicatesBeforeLimitAcrossStudies(){
  for(int n=0;n<12;n++){UUID study=n%2==0?a.studyId():b.studyId();UUID id=task(study,n%3==0?"DRAFT":"OPEN");if(n%3==1)submit(study,id,actor);if(n%3==2)submit(study,id,f.f.ids.next());}assertEquals(12,list("ALL",null,100).items().size());assertEquals(4,list("OPEN_NOT_SUBMITTED",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("OPEN_NOT_SUBMITTED",after,2);seen.addAll(p.items().stream().map(CourseMyAssignmentsStore.Row::assignmentId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("OPEN_NOT_SUBMITTED",null,100).items().stream().map(CourseMyAssignmentsStore.Row::assignmentId).toList(),seen);assertEquals(4,new HashSet<>(seen).size());
 }
 @Test void foreignCourseScopeInvalidFiltersAndBoundsFailClosed(){
  task(a.studyId(),"OPEN");f.status(404,()->store.list(f.f.ids.next(),f.space,course.courseId(),actor,null,20,"ALL"));f.status(404,()->store.list(f.group,f.f.ids.next(),course.courseId(),actor,null,20,"ALL"));f.status(404,()->store.list(f.group,f.space,f.f.ids.next(),actor,null,20,"ALL"));var empty=f.create(f.f.key()).course();assertTrue(store.list(f.group,f.space,empty.courseId(),actor,null,20,"ALL").items().isEmpty());for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));for(String filter:List.of("open","CURRENT","REQUESTED","","ALL' OR TRUE--"))f.status(400,()->list(filter,null,20));
 }
 @Test void readsNeverEnrollOrChangeCourseStudyAssignmentSubmissionOrOutbox(){
  UUID x=task(a.studyId(),"OPEN");var own=submit(a.studyId(),x,actor);int events=f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:CourseMyAssignmentsStore.FILTERS)list(filter,null,20);assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM course_enrollment WHERE course_id=?",Integer.class,course.courseId()));assertEquals(course,f.store.get(f.group,f.space,course.courseId()));assertEquals(a,f.parent.store.get(f.group,f.space,a.studyId()));assertEquals(own,submissions.get(f.group,f.space,a.studyId(),x,own.submissionId(),actor,false));assertEquals(events,f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void concurrentCurriculumReplacementIsReadAsOneCanonicalStatementSnapshot()throws Exception{
  task(a.studyId(),"OPEN");task(a.studyId(),"OPEN");task(b.studyId(),"OPEN");task(b.studyId(),"OPEN");course=f.curriculum(course,a.studyId());var starting=course;try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reader=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var rows=list("ALL",null,20).items();assertEquals(2,rows.size());assertEquals(1,rows.stream().map(CourseMyAssignmentsStore.Row::studyId).distinct().count());}return true;});var writer=pool.submit(()->{barrier.await();var current=starting;for(int n=0;n<6;n++)current=f.curriculum(current,n%2==0?b.studyId():a.studyId());return current;});assertTrue(reader.get(20,TimeUnit.SECONDS));course=writer.get(20,TimeUnit.SECONDS);assertEquals(a.studyId(),list("ALL",null,20).items().getFirst().studyId());}
 }
}
